var html = $input.first().json.data;
var lang = $('Webhook').first().json.body.language || 'Deutsch (DE)';

var visibleHtml = html
  .replace(/<head[\s\S]*?<\/head>/gi, '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<script[\s\S]*?<\/script>/gi, '');
var visibleText = visibleHtml
  .replace(/<[^>]+>/g, ' ')
  .replace(/&ndash;/gi,'–').replace(/&mdash;/gi,'—').replace(/&#8211;/g,'–').replace(/&#8212;/g,'—').replace(/&[a-zA-Z#][a-zA-Z0-9]+;/g,' ')
  .replace(/\s+/g, ' ').trim();

function cleanText(raw) {
  var r = raw || '';
  for (var i=0; i<3; i++) r = r.replace(/<[^>]*>/g,' ');
  r = r.replace(/&lt;/gi,'<').replace(/&gt;/gi,'>').replace(/&amp;/gi,'&')
       .replace(/&nbsp;/gi,' ').replace(/&#160;/g,' ')
       .replace(/&#\d+;/g,' ').replace(/&[a-zA-Z]+;/g,' ');
  return r.replace(/\s+/g,' ').trim();
}
function parseColor(s) {
  if (!s) return null;
  s = s.trim().toLowerCase().replace(/\s+/g,'');
  var named = {
    white:{r:255,g:255,b:255}, black:{r:0,g:0,b:0},
    red:{r:255,g:0,b:0}, blue:{r:0,g:0,b:255}, navy:{r:0,g:0,b:128},
    green:{r:0,g:128,b:0}, lime:{r:0,g:255,b:0},
    gray:{r:128,g:128,b:128}, grey:{r:128,g:128,b:128},
    silver:{r:192,g:192,b:192}, orange:{r:255,g:165,b:0},
    yellow:{r:255,g:255,b:0}, purple:{r:128,g:0,b:128},
    lightgray:{r:211,g:211,b:211}, lightgrey:{r:211,g:211,b:211},
    darkgray:{r:169,g:169,b:169}, darkgrey:{r:169,g:169,b:169}
  };
  if (named[s]) return named[s];
  if (s==='transparent'||s==='none'||s==='inherit'||s==='currentcolor') return null;
  var hex = s.match(/^#?([0-9a-f]{3,8})$/);
  if (hex) {
    var h = hex[1];
    if (h.length===3) h=h[0]+h[0]+h[1]+h[1]+h[2]+h[2];
    if (h.length===6||h.length===8) return {r:parseInt(h.substr(0,2),16),g:parseInt(h.substr(2,2),16),b:parseInt(h.substr(4,2),16)};
  }
  var rgb = s.match(/^rgba?\((\d+),(\d+),(\d+)/);
  if (rgb) return {r:+rgb[1],g:+rgb[2],b:+rgb[3]};
  return null;
}
function luminance(c) {
  if (!c) return null;
  var r=c.r/255, g=c.g/255, b=c.b/255;
  r = r<=0.03928 ? r/12.92 : Math.pow((r+0.055)/1.055,2.4);
  g = g<=0.03928 ? g/12.92 : Math.pow((g+0.055)/1.055,2.4);
  b = b<=0.03928 ? b/12.92 : Math.pow((b+0.055)/1.055,2.4);
  return 0.2126*r + 0.7152*g + 0.0722*b;
}
function contrast(c1,c2) {
  if (!c1||!c2) return null;
  var l1=luminance(c1), l2=luminance(c2);
  if (l1===null||l2===null) return null;
  var hi=Math.max(l1,l2), lo=Math.min(l1,l2);
  return (hi+0.05)/(lo+0.05);
}

var wcag = [];

