  var px = unit==='px'?val:unit==='pt'?val*1.333:unit==='em'||unit==='rem'?val*16:val;
  if (px > 0 && px < 15.5) {
    var _fsTE = (function(h, pos) {
      var to = h.lastIndexOf('<', pos); if (to < 0) return -1;
      var i = to+1, inQ=false, qC='', lim=Math.min(h.length, to+4000);
