  var uniqFs = [...new Set(fontSizeItems)];
  wcag.push({criterion:'1.4.4', issue:uniqFs.length+' Textelement(e) mit Schriftgrösse unter 16px (EAA-Mindestgrösse)', examples:uniqFs.slice(0,6), severity:'hinweis'});
}

// 1.4.3 contrast
var contrastIssues = [];
