  var fsPx = 16;
  if (fsInM) { var v=parseFloat(fsInM[1]),u=fsInM[2].toLowerCase(); fsPx=u==='px'?v:u==='pt'?v*1.333:v*16; }
  var required = fsPx >= 18 ? 3.0 : 4.5;
  if (ratio < required) {
    var toHex = function(c){ return '#'+[c.r,c.g,c.b].map(function(x){return x.toString(16).padStart(2,'0');}).join(''); };
    var _tagEnd = (function(h, pos) {
      var to = h.lastIndexOf('<', pos); if (to < 0) return -1;
      var i = to+1, inQ=false, qC='', lim=Math.min(h.length, to+4000);
      while(i<lim){var c=h[i];if(inQ){if(c===qC)inQ=false;}else if(c=='"'||c==="'"){inQ=true;qC=c;}else if(c==='>'){return i;}i++;}return -1;
    })(visibleHtml, inlineM.index);
    if (_tagEnd < 0) continue;
    var _raw = visibleHtml.substring(_tagEnd+1, _tagEnd+2001);
    var _firstTag = _raw.indexOf('<');
    var _directTxt = (_firstTag > 0 ? _raw.substring(0, _firstTag) : '')
      .replace(/&nbsp;/gi,' ').replace(/&#160;/g,' ').replace(/&[a-zA-Z#][a-zA-Z0-9]+;/g,' ').replace(/\s+/g,' ').trim();
    var textSnip;
    if (_directTxt.length >= 3) {
      textSnip = _directTxt.substring(0, 40);
    } else {
      textSnip = _raw.replace(/<[^>]+>/g,' ').replace(/&nbsp;/gi,' ').replace(/&#160;/g,' ').replace(/&[a-zA-Z#][a-zA-Z0-9]+;/g,' ').replace(/\s+/g,' ').trim().substring(0, 40);
    }
    if (!textSnip) continue;
    var fgHex=toHex(fg), bgHex=toHex(bg);
    if (fgHex === bgHex) continue;
    var ratioStr = ratio.toFixed(1)+':1 (Minimum '+required.toFixed(1)+':1)';
