}

// 2.4.4 generische CTA-Linktexte
var genericCtaRe = /^(mehr erfahren|hier klicken|klicken sie hier|hier|weiter|mehr|lesen sie mehr|jetzt klicken|click here|read more|en savoir plus|plus d.infos|d.couvrir|saperne di pi.?|clicca qui|scopri di pi.?)$/i;
