    H+='<tr><td>'+critCell+'</td><td>'+esc(f.issue)+'</td><td>'+exCell+'</td><td>'+sev(f.severity)+'</td></tr>';
  });
  H+='</tbody></table></div>';
}else{H+='<div class="cb-ok">&#10003; Keine WCAG-Verstösse.</div>';}
H+='</div>';

H+='</main><div class="ft">swisscom AG · Newsletter Qualitätsprüfung · Styleguide 2025 · '+langBadge+' · '+now+'</div></body></html>';
return [{ json: { report: H } }];

